  transition: transform 0.3s ease;
}
.text-link:hover::after {
  transform: translateX(4px);
}
.text-link:hover {
  color: var(--brand-gold);
}

.text-link-light {
  color: var(--text-light);
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}
.text-link-light::after {
  content: "→";
  transition: transform 0.3s ease;
}
.text-link-light:hover::after {
  transform: translateX(4px);
}
.text-link-light:hover {
  color: var(--brand-gold);
}

/* Utilities */
.text-center { text-align: center; }
.mt-2 { margin-top: var(--space-2); }
.mt-4 { margin-top: var(--space-4); }
.mt-8 { margin-top: var(--space-8); }
.mb-2 { margin-bottom: var(--space-2); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }
.py-8 { padding-top: var(--space-8); padding-bottom: var(--space-8); }
.py-12 { padding-top: var(--space-12); padding-bottom: var(--space-12); }
.py-16 { padding-top: var(--space-16); padding-bottom: var(--space-16); }
.bg-subtle { background-color: var(--bg-subtle); }
.bg-navy { background-color: var(--brand-navy); color: var(--text-light); }
.bg-navy h2, .bg-navy h3, .bg-navy h4 { color: var(--text-light); }

.grid {
  display: grid;
  gap: var(--space-6);
}

/* Typography styles */
.section-title {
  font-size: 2.5rem;
  margin-bottom: var(--space-4);
}
.section-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 800px;
  margin-bottom: var(--space-8);
}
.bg-navy .section-subtitle {
  color: oklch(85% 0.02 250);
}

/* Header & Navigation */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  transition: background-color var(--transition);
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--brand-navy);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--brand-gold);
}

.main-nav {
  display: flex;
  gap: var(--space-6);
  height: 100%;
}

.nav-item {
  display: flex;
  align-items: center;
  height: 100%;
  position: relative;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
}

.nav-item:hover {
  color: var(--brand-gold);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 100vw;
  max-width: var(--container-max);
  background-color: var(--bg-surface);
  box-shadow: 0 10px 30px rgba(0,0,0,0.05);
  border: 1px solid var(--border-color);
  border-top: none;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
  padding: var(--space-8) var(--space-4);
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--space-8);
  z-index: 100;
}

.nav-item:hover .mega-menu {
  opacity: 1;
  visibility: visible;
}

.mega-menu-section h4 {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--border-color);
}

.mega-menu-list {
  display: grid;
  gap: var(--space-3);
}

.mega-menu-list a {
  font-size: 1rem;
  font-weight: 500;
  display: block;
  text-transform: none;
  letter-spacing: normal;
  color: var(--text-primary);
}

.mega-menu-list a:hover {
  color: var(--brand-gold);
  transform: translateX(4px);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.5rem;
  color: var(--brand-navy);
}

/* Mobile Nav Accordion */
.mobile-nav {
  display: none;
  position: fixed;
  top: 80px;
  left: 0;
  width: 100%;
  height: calc(100vh - 80px);
  background-color: var(--bg-surface);
  padding: var(--space-4);
  overflow-y: auto;
  z-index: 99;
}

.mobile-nav.active {
  display: block;
}

.mobile-nav-item {
  border-bottom: 1px solid var(--border-color);
}

.mobile-nav-btn {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-4) 0;
  background: none;
  border: none;
  font-size: 1.125rem;
  font-weight: 500;
  font-family: var(--font-sans);
  text-transform: uppercase;
  color: var(--brand-navy);
  cursor: pointer;
}

.mobile-nav-link {
  display: block;
  padding: var(--space-4) 0;
  font-size: 1.125rem;
  font-weight: 500;
  text-transform: uppercase;
  color: var(--brand-navy);
}

.mobile-nav-sub {
  display: none;
  padding-bottom: var(--space-4);
  padding-left: var(--space-4);
}

.mobile-nav-sub.active {
  display: block;
}

.mobile-nav-sub a {
  display: block;
  padding: var(--space-2) 0;
  color: var(--text-secondary);
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-color: var(--brand-navy);
  color: var(--text-light);
  overflow: hidden;
}

.hero-sm {
  min-height: 50vh;
}

.hero-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.4;
  mix-blend-mode: multiply;
}

.hero-content {
  position: relative;
  z-index: 10;
  max-width: 800px;
}

.hero-title {
  font-size: clamp(3rem, 5vw, 4.5rem);
  color: var(--text-light);
  margin-bottom: var(--space-4);
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--bg-subtle);
  margin-bottom: var(--space-6);
  max-width: 600px;
}

/* Announcement Banner */
.announcement-banner {
  background-color: var(--brand-gold);
  color: var(--brand-navy);
  padding: var(--space-3) 0;
  text-align: center;
  font-weight: 500;
}
.announcement-banner a {
  text-decoration: underline;
  margin-left: var(--space-2);
}

/* Featured Insights (Homepage) */
.featured-insights-grid {
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  margin-top: calc(-1 * var(--space-12));
  position: relative;
  z-index: 20;
}

.insight-card {
  background: var(--bg-surface);
  padding: var(--space-6);
  border: 1px solid var(--border-color);
  box-shadow: 0 4px 20px rgba(0,0,0,0.05);
  transition: transform var(--transition);
  display: flex;
  flex-direction: column;
}

.insight-card:hover {
  transform: translateY(-5px);
}

.insight-tag {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--brand-gold);
  margin-bottom: var(--space-2);
  font-weight: 600;
}

.insight-title {
  font-size: 1.25rem;
  margin-bottom: var(--space-4);
  font-family: var(--font-sans);
}

.insight-card .text-link {
  margin-top: auto;
}

/* What We Do Tabs */
.tabs-container {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--space-8);
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  border-left: 2px solid var(--border-color);
}

.tab-btn {
  padding: var(--space-4) var(--space-6);
  text-align: left;
  background: none;
  border: none;
  font-size: 1.25rem;
  font-family: var(--font-serif);
  color: var(--text-secondary);
  cursor: pointer;
  position: relative;
  transition: all var(--transition);
}

.tab-btn::before {
  content: "";
  position: absolute;
  left: -2px;
  top: 0;
  height: 100%;
  width: 2px;
  background-color: var(--brand-gold);
  transform: scaleY(0);
  transition: transform var(--transition);
  transform-origin: top;
}

.tab-btn.active {
  color: var(--brand-navy);
  font-weight: 600;
}

.tab-btn.active::before {
  transform: scaleY(1);
}

.tab-content {
  display: none;
  padding: var(--space-4) 0;
  animation: fadeIn 0.5s ease forwards;
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-pane-title {
  font-size: 2rem;
  margin-bottom: var(--space-4);
}

/* Service Category Cards (Services Overview) */
.services-grid {
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.service-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: var(--space-8);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  border-color: var(--brand-gold);
  box-shadow: 0 10px 30px rgba(0,0,0,0.05);
}

.service-card-title {
  font-size: 1.5rem;
  margin-bottom: var(--space-4);
}

.service-card p {
  margin-bottom: var(--space-4);
  color: var(--text-secondary);
}

.service-card .text-link {
  margin-top: auto;
}

/* Capabilities Grid */
.capabilities-grid {
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.capability-card {
  padding: var(--space-6);
  background: var(--bg-subtle);
  border-top: 3px solid var(--brand-navy);
}

.capability-title {
  font-size: 1.25rem;
  font-family: var(--font-sans);
  margin-bottom: var(--space-3);
}

/* Newsletter */
.newsletter-section {
  background-color: var(--brand-navy);
  color: var(--text-light);
  padding: var(--space-12) 0;
  text-align: center;
}

.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: var(--space-6) auto 0;
  gap: 0;
}

.newsletter-form input {
  flex: 1;
  padding: 1rem;
  border: none;
  outline: none;
  font-family: var(--font-sans);
}

.newsletter-form button {
  border-radius: 0;
}

/* Latest Insights Section */
.latest-insights-grid {
  grid-template-columns: repeat(3, 1fr);
}

.latest-insight-card {
  display: flex;
  flex-direction: column;
}

.latest-insight-img {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  background-color: var(--border-color);
  margin-bottom: var(--space-4);
}

.latest-insight-date {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-2);
}

/* Commitment Grid */
.commitment-grid {
  grid-template-columns: repeat(4, 1fr);
}

.commitment-card {
  padding: var(--space-6);
  border: 1px solid var(--border-light);
}

.commitment-title {
  font-size: 1.25rem;
  color: var(--text-light);
  margin-bottom: var(--space-3);
  font-family: var(--font-sans);
}

/* Featured Partners */
.partners-carousel {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  padding-bottom: var(--space-4);
  scroll-snap-type: x mandatory;
}
.partner-card {
  min-width: 300px;
  background: var(--bg-surface);
  padding: var(--space-6);
  border: 1px solid var(--border-color);
  scroll-snap-align: start;
}

/* Sidebar Layout */
.sidebar-layout {
  display: grid;
  grid-template-columns: 3fr 1fr;
  gap: var(--space-8);
}

.sidebar {
  border-left: 1px solid var(--border-color);
  padding-left: var(--space-6);
}

.sidebar h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-4);
  font-family: var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
}

.sidebar ul {
  display: grid;
  gap: var(--space-3);
}

.sidebar a {
  font-size: 1.125rem;
  font-weight: 500;
  display: block;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: var(--space-3);
}
.sidebar a:hover {
  color: var(--brand-gold);
}


/* Footer */
.site-footer {
  background-color: var(--brand-navy);
  color: var(--text-light);
  padding: var(--space-12) 0 var(--space-4);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--space-8);
  margin-bottom: var(--space-8);
}

.footer-col h4 {
  color: var(--text-light);
  font-family: var(--font-sans);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-4);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.footer-links a {
  color: oklch(80% 0.02 250);
  font-size: 0.875rem;
}

.footer-links a:hover {
  color: var(--brand-gold);
}

.footer-bottom {
  padding-top: var(--space-6);
  border-top: 1px solid var(--border-light);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  color: oklch(70% 0.02 250);
}

.footer-legal {
  display: flex;
  gap: var(--space-4);
}

/* Responsive */
@media (max-width: 1024px) {
  .featured-insights-grid,
  .capabilities-grid,
  .sidebar-layout {
    grid-template-columns: repeat(2, 1fr);
  }
  .commitment-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .tabs-container {
    grid-template-columns: 1fr;
  }
  .tabs-nav {
    flex-direction: row;
    overflow-x: auto;
    border-left: none;
    border-bottom: 2px solid var(--border-color);
  }
  .tab-btn {
    text-align: center;
    white-space: nowrap;
  }
  .tab-btn::before {
    left: 0;
    top: auto;
    bottom: -2px;
    width: 100%;
    height: 2px;
    transform: scaleX(0);
    transform-origin: left;
  }
  .tab-btn.active::before {
    transform: scaleX(1);
  }
  .sidebar {
    border-left: none;
    padding-left: 0;
    border-top: 1px solid var(--border-color);
    padding-top: var(--space-6);
  }
}

@media (max-width: 768px) {
  .main-nav {
    display: none;
  }
  .mobile-menu-btn {
    display: block;
  }
  .featured-insights-grid,
  .services-grid,
  .capabilities-grid,
  .latest-insights-grid,
  .commitment-grid,
  .sidebar-layout {
    grid-template-columns: 1fr;
  }
  .featured-insights-grid {
    margin-top: var(--space-4);
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const mobileNav = document.querySelector('.mobile-nav');

  if (mobileMenuBtn && mobileNav) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileNav.classList.toggle('active');
      const isExpanded = mobileNav.classList.contains('active');
      mobileMenuBtn.setAttribute('aria-expanded', isExpanded);
      mobileMenuBtn.innerHTML = isExpanded ? '✕' : '☰';
    });
  }

  // Mobile Accordion
  const mobileNavBtns = document.querySelectorAll('.mobile-nav-btn');
  mobileNavBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetId = btn.getAttribute('data-target');
      const targetSub = document.getElementById(targetId);

      if (targetSub) {
        const isActive = targetSub.classList.contains('active');

        // Close others (optional)
        // document.querySelectorAll('.mobile-nav-sub').forEach(sub => sub.classList.remove('active'));
        // document.querySelectorAll('.mobile-nav-btn').forEach(b => b.innerHTML = b.innerHTML.replace('−', '+'));

        if (isActive) {
          targetSub.classList.remove('active');
          btn.innerHTML = btn.innerHTML.replace('−', '+');
        } else {
          targetSub.classList.add('active');
          btn.innerHTML = btn.innerHTML.replace('+', '−');
        }
      }
    });
  });

  // What We Do Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  if (tabBtns.length > 0 && tabContents.length > 0) {
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all
        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        // Add active class to clicked
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // Set current year in footer
  const yearSpan = document.querySelector('.current-year');
  if (yearSpan) {
    yearSpan.textContent = new Date().getFullYear();
  }
});
